<?php $pageTitle='Track Booking';$theme='pink';require_once 'includes/db.php';$no=trim($_GET['booking_no']??'');$booking=null;if($no){$q=$pdo->prepare('SELECT b.*,v.name vendor,s.name service FROM bookings b LEFT JOIN vendors v ON v.id=b.vendor_id LEFT JOIN services s ON s.id=b.service_id WHERE b.booking_no=?');$q->execute([$no]);$booking=$q->fetch();}include 'includes/header.php';?><section class="py-5"><div class="container"><div class="col-lg-7 mx-auto"><div class="content-card p-4 p-md-5"><h2>Track your booking</h2><form class="input-group my-4"><input name="booking_no" class="form-control" placeholder="BKG-20260819-1234" value="<?=htmlspecialchars($no)?>"><button class="btn btn-brand">Track</button></form><?php if($no&&$booking):?><h4><?=htmlspecialchars($booking['booking_no'])?></h4><p><b>Event:</b> <?=htmlspecialchars($booking['event_type'])?> · <?=htmlspecialchars($booking['event_date'])?></p><p><b>Service:</b> <?=htmlspecialchars($booking['service']??$booking['vendor']??'Requested service')?></p><div class="progress" style="height:12px"><div class="progress-bar" style="width:<?=match($booking['status']){'Pending'=>20,'Confirmed'=>40,'In Progress'=>65,'Completed'=>100,'Cancelled'=>100}?>%;background:var(--pink)"></div></div><div class="d-flex justify-content-between small mt-2"><span>Submitted</span><span>Confirmed</span><span>In Progress</span><span>Completed</span></div><div class="alert alert-light mt-4">Current status: <b><?=htmlspecialchars($booking['status'])?></b></div><?php elseif($no):?><div class="alert alert-warning">Booking number not found.</div><?php endif;?></div></div></div></section><?php include 'includes/footer.php'; ?>
